import { eegStudies as eegStudiesCollection } from "../config/mongoCollections.js";
import { ObjectId } from "mongodb";
import { validateId } from "./helper.js";

/**
 * EEG Study Model
 *
 * Represents an EEG analysis study as a first-class entity (decoupled from Patient).
 *
 * CURRENT STRUCTURE (migrated from patient.eegVisuals):
 * {
 *   _id: ObjectId,
 *   patientId: ObjectId,              // Reference to patients collection
 *   uploadId: string,                 // UUID generated by Python service
 *   status: string,                   // "UPLOADED" | "PROCESSING" | "COMPLETED" | "FAILED"
 *   title: string | null,             // Optional study title (e.g., "Pre-surgery baseline")
 *   uploadDate: Date | null,          // When the EEG file was uploaded
 *   completionDate: Date | null,      // When processing completed
 *   summary: string | null,           // e.g., "Highest activity in left temporal lobe"
 *   hotspots: Array,                  // Future: [{region, confidence, coordinates}]
 *   figureUrls: {
 *     topomap: string | null,         // Cloudinary URL for EEG topomap
 *     brainViews: [string],           // 11 Cloudinary URLs for brain views
 *     annotated: [string]             // Future: annotated brain images
 *   },
 *   reportUrl: string | null,         // Future: PDF report URL
 *   errorMessage: string | null,      // Error message if status is "FAILED"
 *   processingTime: number | null,    // Processing duration in seconds
 *   metadata: {
 *     modelVersion: string | null,    // ML model version used
 *     mneVersion: string | null       // MNE library version
 *   },
 *   createdAt: Date,                  // Timestamp of record creation
 *   updatedAt: Date                   // Timestamp of last update
 * }
 */

const exportedMethods = {
  /**
   * Create a new EEG study
   * @param {Object} studyData - Study data object
   * @returns {Promise<Object>} Created study document
   */
  async createStudy(studyData) {
    // Validate required fields
    if (!studyData.patientId) {
      throw new Error("patientId is required");
    }
    if (!studyData.uploadId) {
      throw new Error("uploadId is required");
    }

    // Validate patientId format
    const patientId = validateId(studyData.patientId, "patient id");

    const collection = await eegStudiesCollection();

    // Check if study with this uploadId already exists
    const existingStudy = await collection.findOne({
      uploadId: studyData.uploadId,
    });

    if (existingStudy) {
      throw new Error(
        `Study with uploadId ${studyData.uploadId} already exists`
      );
    }

    // Build study document with defaults
    const now = new Date();
    const newStudy = {
      patientId: ObjectId.createFromHexString(patientId),
      uploadId: studyData.uploadId,
      status: studyData.status || "COMPLETED",
      title: studyData.title || null,
      uploadDate: studyData.uploadDate || null,
      completionDate: studyData.completionDate || null,
      summary: studyData.summary || null,
      hotspots: studyData.hotspots || [],
      figureUrls: {
        topomap: studyData.figureUrls?.topomap || null,
        brainViews: studyData.figureUrls?.brainViews || [],
        annotated: studyData.figureUrls?.annotated || [],
      },
      reportUrl: studyData.reportUrl || null,
      errorMessage: studyData.errorMessage || null,
      processingTime: studyData.processingTime || null,
      metadata: {
        modelVersion: studyData.metadata?.modelVersion || null,
        mneVersion: studyData.metadata?.mneVersion || null,
      },
      createdAt: now,
      updatedAt: now,
    };

    const insertResult = await collection.insertOne(newStudy);

    if (!insertResult.insertedId) {
      throw new Error("Failed to insert study");
    }

    return await this.getStudyById(insertResult.insertedId.toString());
  },

  /**
   * Get study by _id
   * @param {string} id - Study _id
   * @returns {Promise<Object|null>} Study document or null
   */
  async getStudyById(id) {
    id = validateId(id, "study id");
    const collection = await eegStudiesCollection();
    const study = await collection.findOne({
      _id: ObjectId.createFromHexString(id),
    });
    return study;
  },

  /**
   * Find study by uploadId
   * @param {string} uploadId - Upload UUID
   * @returns {Promise<Object|null>} Study document or null
   */
  async findByUploadId(uploadId) {
    if (typeof uploadId !== "string" || !uploadId.trim()) {
      throw new Error("uploadId must be a non-empty string");
    }

    const collection = await eegStudiesCollection();
    const study = await collection.findOne({ uploadId });
    return study;
  },

  /**
   * Find all studies for a patient
   * @param {string} patientId - Patient _id
   * @returns {Promise<Array>} Array of study documents (sorted by uploadDate desc)
   */
  async findByPatientId(patientId) {
    patientId = validateId(patientId, "patient id");
    const collection = await eegStudiesCollection();

    const studies = await collection
      .find({
        patientId: ObjectId.createFromHexString(patientId),
      })
      .sort({ uploadDate: -1 }) // Most recent first
      .toArray();

    return studies;
  },

  /**
   * Update study status
   * @param {string} id - Study _id
   * @param {string} status - New status
   * @returns {Promise<Object>} Updated study document
   */
  async updateStatus(id, status) {
    id = validateId(id, "study id");

    const validStatuses = ["UPLOADED", "PROCESSING", "COMPLETED", "FAILED"];
    if (!validStatuses.includes(status)) {
      throw new Error(
        `Invalid status. Must be one of: ${validStatuses.join(", ")}`
      );
    }

    const collection = await eegStudiesCollection();
    const updateResult = await collection.findOneAndUpdate(
      { _id: ObjectId.createFromHexString(id) },
      {
        $set: {
          status,
          updatedAt: new Date(),
        },
      },
      { returnDocument: "after" }
    );

    if (!updateResult) {
      throw new Error(`Study with id ${id} not found`);
    }

    return updateResult;
  },

  /**
   * Update study with processing results
   * @param {string} uploadId - Upload UUID
   * @param {Object} results - Processing results
   * @returns {Promise<Object>} Updated study document
   */
  async updateProcessingResults(uploadId, results) {
    if (typeof uploadId !== "string" || !uploadId.trim()) {
      throw new Error("uploadId must be a non-empty string");
    }

    const collection = await eegStudiesCollection();

    const updateData = {
      updatedAt: new Date(),
    };

    // Update only provided fields
    if (results.status) updateData.status = results.status;
    if (results.completionDate) updateData.completionDate = results.completionDate;
    if (results.summary) updateData.summary = results.summary;
    if (results.hotspots) updateData.hotspots = results.hotspots;
    if (results.figureUrls) updateData.figureUrls = results.figureUrls;
    if (results.reportUrl) updateData.reportUrl = results.reportUrl;
    if (results.errorMessage) updateData.errorMessage = results.errorMessage;
    if (results.processingTime) updateData.processingTime = results.processingTime;
    if (results.metadata) updateData.metadata = results.metadata;

    const updateResult = await collection.findOneAndUpdate(
      { uploadId },
      { $set: updateData },
      { returnDocument: "after" }
    );

    if (!updateResult) {
      throw new Error(`Study with uploadId ${uploadId} not found`);
    }

    return updateResult;
  },

  /**
   * Delete a study
   * @param {string} id - Study _id
   * @returns {Promise<Object>} Deletion result
   */
  async deleteStudy(id) {
    id = validateId(id, "study id");
    const collection = await eegStudiesCollection();

    const deleteResult = await collection.findOneAndDelete({
      _id: ObjectId.createFromHexString(id),
    });

    if (!deleteResult) {
      throw new Error(`Study with id ${id} not found`);
    }

    return { _id: deleteResult._id, deleted: true };
  },

  /**
   * Get all studies (with optional filters)
   * @param {Object} filters - Optional filters
   * @returns {Promise<Array>} Array of study documents
   */
  async getAllStudies(filters = {}) {
    const collection = await eegStudiesCollection();
    const query = {};

    if (filters.status) {
      query.status = filters.status;
    }

    if (filters.patientId) {
      query.patientId = ObjectId.createFromHexString(
        validateId(filters.patientId, "patient id")
      );
    }

    const studies = await collection
      .find(query)
      .sort({ createdAt: -1 })
      .toArray();

    return studies;
  },
};

export default exportedMethods;
